        self.assertEqual(render("{{a}}|{{ a }}|{{   a   }}", ctx), "x|x|x")
        self.assertEqual(render("{{ u.n }} {{ u.deep.k }} {{ u.tags.1 }} {{ u.tags.0 }}", ctx), "Ada 1 q p")

    def test_missing_is_empty(self):
        self.assertEqual(render("[{{ nope }}][{{ u.nope }}][{{ u.tags.5 }}][{{ a.b }}]", {"u": {"tags": [1]}, "a": "s"}), "[][][][]")

