        ctx = {"n": None, "t": True, "f": False, "z": 0, "fl": 2.5, "l": [1, "a", None, True, [2, 3]], "e": ""}
        self.assertEqual(render("{{n}}|{{t}}|{{f}}|{{z}}|{{fl}}|{{l}}|{{e}}|", ctx), "|true|false|0|2.5|1, a, , true, 2, 3||")

