                    "{{ a | }}", "{{ | upper }}", '{{ a | default "x }}', "{{ a | pad 1 2 }}", "{{ a b }}", "{{ }}"):
            with self.assertRaises(TemplateError, msg=tpl):
                render(tpl, {"a": 1})


class Conditionals(unittest.TestCase):
