    toks = []
    pos = 0
    strip_next = False
    pending = []

    def flush():
        text = "".join(pending)
        del pending[:]
        if text:
            toks.append(("text", text))

    for m in _TAG.finditer(src):
        text = src[pos:m.start()]
        pos = m.end()
        if strip_next:
            text = text.lstrip()
            strip_next = False
        if text.endswith("\\"):
            pending.append(text[:-1] + m.group(0))
            continue
        if m.group(1) == "-":
            text = text.rstrip()
        pending.append(text)
        flush()
        toks.append(("tag", m.group(2).strip()))
        strip_next = m.group(3) == "-"
    tail = src[pos:]
    if strip_next:
        tail = tail.lstrip()
    pending.append(tail)
    flush()
    return toks


